mapper.select:
SELECT id AS barId,
       name,
       avatar_url AS avatarUrl,
       follower_count AS followerCount,
       post_count AS postCount
FROM bar
WHERE status = 0
  AND deleted = 0
  AND name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'

    AND (
        follower_count < #{cursor.followerCount}
        OR (
            follower_count = #{cursor.followerCount}
            AND post_count < #{cursor.postCount}
        )
        OR (
            follower_count = #{cursor.followerCount}
            AND post_count = #{cursor.postCount}
            AND id < #{cursor.barId}
        )
    )

ORDER BY follower_count DESC, post_count DESC, id DESC
LIMIT #{pageSize}
